async function getData() {
  const userPromise = fetch("/api/user");
  const postsPromise = fetch("/api/posts");
  const commentsPromise = fetch("/api/comments");

  const [user, posts, comments] = await Promise.all([
    userPromise,
    postsPromise,
    commentsPromise
  ]);

  console.log(user);
  console.log(posts);
  console.log(comments);
}

getData();

